#pragma once

// The generic host kit for Verus accelerators (query-agnostic; TRUSTED GLUE).
//
// A Verus accelerator plugs into the engines through three pieces:
//   * its kernel's C ABI (generated by sql2verus: <crate>_verus.h);
//   * its host glue (generated by sql2verus --host-glue: gen_glue.cpp), which
//     runs the declared scans through a Host, marshals captured changes into
//     the C ABI, and registers a Glue for the query;
//   * this kit: the registry, the cell conversions the glue uses, and a
//     generic AuxQueryModule and Verus-store adapter driven by the Glue.
// An engine provides a Host (run SQL, resolve column numbers) and a binding
// that finds registered Glues (see the engine runtimes).  A new query adds
// only its own generated files: nothing shared is edited.
//
// Cells convert exactly or throw Declined (a value outside the kernel's runtime
// type, e.g. a non-finite DOUBLE): the module then rebuilds or answers with SQL.
// A NULL cell throws too, except where the glue tests IsNull first: the kernel's
// NULL-able fields carry an explicit flag.
//
// Fault injection (tests only): ACCEL_VERUS_KIT_FAULT selects one deliberate
// bug, so a test suite can show that it catches it:
//   skip_apply           commits leave the state unchanged
//   drop_delta:<table>   the table's changes are dropped
//   no_rescan            rescans return no rows
//   ignore_snapshot      readers see the newest version (Verus store)
//
// Record mode (glue contract checks): with ACCEL_VERUS_RECORD_DIR set, the
// generated C ABI logs every row the glue passes and returns without calling
// the kernel; commits call the glue's apply path with no state and change
// nothing.

#include <cstddef>
#include <cstdint>
#include <functional>
#include <memory>
#include <stdexcept>
#include <string>
#include <vector>

#include "substrate/aux/core/aux_types.hpp"
#include "substrate/aux/state/verus_aux_store.hpp"

namespace accelerator_codegen::verus_kit {

namespace core = ::accelerator_codegen::aux_state::core;

struct Declined : std::runtime_error {
  using std::runtime_error::runtime_error;
};

// ---- cells (row i-th value) ----
// An integer or decimal as value * 10^scale, exactly.
int64_t I64(const core::AuxRow &row, std::size_t i, int scale);
// A date as days since 1970-01-01.
int32_t Date(const core::AuxRow &row, std::size_t i);
// A timestamp as nanoseconds since 1970-01-01 00:00:00 (no time zone).
int64_t Ts(const core::AuxRow &row, std::size_t i);
// A boolean as 0 / 1.
uint8_t Bool(const core::AuxRow &row, std::size_t i);
// A DOUBLE as its IEEE-754 bits (Declined if NaN or infinite: outside the kernel's type).
uint64_t F64(const core::AuxRow &row, std::size_t i);
// Whether the cell is NULL (a missing cell counts as NULL).
bool IsNull(const core::AuxRow &row, std::size_t i);
// The text of a NULL cell, for a NULL-able field's value slot.
extern const std::string kNoText;
// Text bytes.
const std::string &Text(const core::AuxRow &row, std::size_t i);

// A text column of the C ABI: concatenated bytes and n + 1 offsets.
struct TextColumn {
  std::vector<uint8_t> bytes;
  std::vector<std::size_t> off{0};
  void Push(const std::string &text) {
    bytes.insert(bytes.end(), text.begin(), text.end());
    off.push_back(bytes.size());
  }
};

// ---- query arguments (false: NULL or not convertible: answer with SQL) ----
// The argument is SQL NULL.  Only for a parameter the kernel declares NULL-able (Option in its
// spec); the other Arg* functions return false on NULL, which answers with SQL.
bool ArgIsNull(const core::QueryArguments &args, std::size_t i);
bool ArgText(const core::QueryArguments &args, std::size_t i, std::string &out);
bool ArgI64(const core::QueryArguments &args, std::size_t i, int scale, int64_t &out);
bool ArgDate(const core::QueryArguments &args, std::size_t i, int32_t &out);
// Why the last Arg* call returned false ("argument 1: NULL", ...); empty after ClearArgFailure.
// An execute that returns false with no argument failure came from the kernel declining.
void ClearArgFailure();
struct ArgFailure {
  std::string what;
  bool outside_type = false; // NULL / not representable in the parameter's type, vs a host conversion fault
};
ArgFailure LastArgFailure();

// ---- result cells ----
core::AuxValue OutText(const uint8_t *bytes, std::size_t len);
core::AuxValue OutI64(int64_t v);
core::AuxValue OutDate(int32_t days);
core::AuxValue OutBool(uint8_t v);
// A DOUBLE from its IEEE-754 bits.
core::AuxValue OutF64(uint64_t bits);
// A timestamp (nanoseconds since the epoch) as exact text.
core::AuxValue OutTs(int64_t ns);
// An i128 decimal (value * 10^scale) as exact text.
core::AuxValue OutDec(int64_t hi, uint64_t lo, int scale);
// A fraction num / den as a double.
core::AuxValue OutRat(int64_t num_hi, uint64_t num_lo, int64_t den_hi, uint64_t den_lo);
core::AuxValue OutNull(core::AuxType type);

// ---- the engine ----
using RowFn = std::function<void(const core::AuxRow &)>;

class Host {
public:
  virtual ~Host() = default;
  // Run `sql` on the database as the current transaction sees it (its own
  // writes included), one row of values per result row.
  virtual void Query(const std::string &sql, const RowFn &row) = 0;
  // Run `sql` with $1, $2, ... bound to `params`.
  virtual void QueryParams(const std::string &sql, const std::vector<core::AuxValue> &params,
                           const RowFn &row) = 0;
  // Run `sql` with $1 bound to a BIGINT[] of `list` (no per-element parse
  // cost). Returns false, without running anything, if the engine has no such
  // path; QueryKeys then inlines the list as a literal.
  virtual bool QueryBigintList(const std::string &, const std::vector<int64_t> &, const RowFn &) { return false; }
  // The engine's attribute numbers (0-based) of table.columns, by name.
  virtual std::vector<int32_t> Attnums(const std::string &table,
                                       const std::vector<std::string> &columns) = 0;
  // A quoted identifier.
  virtual std::string Quote(const std::string &identifier) const;
  // A text literal (standard SQL: quotes doubled).
  virtual std::string QuoteText(const std::string &text) const;
};

// Rows of `sql` whose output column `key_column` is one of `keys`, in chunks.
void QueryKeys(Host &host, const std::string &sql, const std::string &key_column,
               const std::vector<int64_t> &keys, const RowFn &row);
// The same for text keys (compared as bytes; a NULL key matches none).
void QueryKeys(Host &host, const std::string &sql, const std::string &key_column,
               const std::vector<std::string> &keys, const RowFn &row);

// ---- one query's glue ----
struct Change {
  core::AuxRow row; // the table's captured columns
  int64_t sign = 0; // +1 insert, -1 delete
};
using Changes = std::vector<std::vector<Change>>; // per table, in Glue::tables order

enum class Kind { Int, Dec, Date, Text, Bool };

struct TableDecl {
  const char *name;
  std::vector<const char *> columns; // captured columns, by name
};

// The head of the newest version, for a build to stage on: called by the glue after its
// scans, once (the caller releases it); throws if no version can follow the newest.
using HeadFn = std::function<const void *()>;

// The kernel's per-accelerator Verus-store C ABI (<p>s_*), type-erased:
// only for the legacy ACCEL_AUX_STORE=verus (Glue::store); the world's accelerators use
// its base / head / staged / reading / answer functions too.
struct StoreOps {
  void *(*new_store)();
  void (*free_store)(void *);
  void *(*newest_base)(const void *);
  const void *(*base_state)(const void *);
  void (*base_free)(void *);
  void *(*newest_head)(const void *);
  void (*head_free)(void *);
  void *(*stage_invalid)(const void *head);
  void (*staged_free)(void *);
  int32_t (*begin)(const void *, uint64_t);
  void (*abort)(const void *);
  int32_t (*install)(const void *, void *, uint64_t, uint64_t, int32_t);
  const void *(*read)(const void *, uint64_t, uint64_t, int32_t *);
  void (*reading_free)(const void *);
  void (*invalidate_all)(const void *);
  std::size_t (*version_count)(const void *);
  std::size_t (*heap_bytes)();      // the library's live Rust heap (substrate/verus/heap)
  std::size_t (*heap_peak_bytes)(); // its peak since the last reset
  void (*heap_reset_peak)();
};

struct Glue {
  const char *id;       // accelerator id (table function accel_<id>)
  const char *workload; // catalog workload ("tpch", "sec_edgar")
  int query_id;         // catalog query number
  const char *query_sql; // the query, $n parameters (fallback)
  std::vector<TableDecl> tables;
  std::vector<Kind> params;
  // Kernel states owned by the host (host store): build (null: declined),
  // free, apply one transaction (null with *err: rebuild), execute (false:
  // answer with SQL).
  void *(*build)(Host &);
  void (*free_state)(void *);
  void *(*apply)(const void *state, const Changes &, Host &, int32_t *err);
  bool (*execute)(const void *state, const core::QueryArguments &, std::vector<core::AuxRow> &);
  // Verus stores (ACCEL_AUX_STORE=verus, verus_global).  answer: the query on a reading of
  // the store (the verified Theorem 5.4 function; false: answer with SQL).  prepare_apply:
  // the next slot from the newest version's base (the keys to rescan come from its state) and
  // one transaction (null with *err: rebuild); prepare_build: the next slot built from the
  // scans, on the head `head` returns (never null: an invalid slot if declined).
  bool (*answer)(const void *reading, const core::QueryArguments &, std::vector<core::AuxRow> &) = nullptr;
  void *(*prepare_apply)(const void *base, const Changes &, Host &, int32_t *err) = nullptr;
  void *(*prepare_build)(const HeadFn &head, Host &) = nullptr;
  StoreOps store = {};
  // Optional streaming execute: calls `emit` once per answer row, in order,
  // without building the answer as a std::vector<AuxRow>; the row passed to
  // `emit` may be reused by the glue between calls (the sink copies cells out
  // before returning).  Same false-means-fallback contract as `execute`, and
  // false must be returned before the first emit.  When null the generic module
  // uses `execute`.  Host-owned states only.
  bool (*execute_into)(const void *state, const core::QueryArguments &, const RowFn &emit) = nullptr;
};

void Register(const Glue *glue);
const Glue *Find(const std::string &accelerator_id);
std::vector<const Glue *> All();

struct Registrar {
  explicit Registrar(const Glue *glue) { Register(glue); }
};

// Table ids of a glue's tables in mutation batches: 1, 2, ... in order.
inline core::TableId TableIdOf(std::size_t index) { return static_cast<core::TableId>(index + 1); }

// The query's AuxQueryModule: SQL through `host` (which must outlive it);
// the state in the services' store, or the query's Verus store when the
// services' store is one (MakeStore).
std::unique_ptr<core::AuxQueryModule> MakeModule(const Glue &glue, Host &host);

// The query's verified Verus store (the C++ face of its <p>s_* ABI).
std::unique_ptr<aux_state::VerusAuxStore> MakeStore(const Glue &glue,
                                                    aux_state::VerusAuxStore::EpochProvider epoch,
                                                    aux_state::VerusAuxStore::FloorProvider floor);

// A benchmark's world (scripts/gen_verus_world.py): ONE verified store for
// every accelerator it names -- one reader-writer lock, one version per
// database commit, every accelerator's slot answering for the same database
// version -- registered by its generated world_glue.cpp.  With
// ACCEL_AUX_STORE=verus_global each accelerator's store is its view of it
// (MakeWorldStore).
struct WorldKitOps {
  const char *accelerator;
  void *(*base)(const void *gbase); // its state of the base, for prepare_apply (the kit's base_free); NULL: invalid
  void *(*head)(const void *gbase); // its head of the base, for prepare_build (the kit's head_free)
  int32_t (*put)(void *batch, void *staged, uint64_t from); // consumes the staged slot; 0: another base or commit, invalid
  void (*put_invalid)(void *batch);
  const void *(*read)(const void *store, uint64_t at, uint64_t tries, int32_t *status); // a reading
  void (*release)(const void *reading);
  void (*invalidate)(const void *store);
};
struct World {
  const char *bench;
  void *(*new_store)();
  void (*free_store)(void *store);
  int32_t (*begin)(const void *store, uint64_t from); // 1: marked; 0: one in flight
  void (*abort)(const void *store);
  void *(*gbase_new)(const void *store); // the newest version as a base; NULL: none can follow
  uint64_t (*newest)(const void *store);
  void (*gbase_free)(void *gbase);
  void *(*batch_new)(const void *gbase, uint64_t from); // for the commit visible from `from`
  void (*batch_free)(void *batch);
  int32_t (*install)(const void *store, void *batch, uint64_t floor, int32_t end_commit); // current from the batch's epoch
  size_t (*version_count)(const void *store);
  size_t (*heap_bytes)();      // the world library's live Rust heap (substrate/verus/heap)
  size_t (*heap_peak_bytes)(); // its peak since the last reset
  void (*heap_reset_peak)();
  std::vector<WorldKitOps> kits;
};
void RegisterWorld(const World *world);

// The accelerator's view of the world that names it, or null if none does.
// One world store per process (the host serves one database per process).
std::unique_ptr<aux_state::VerusAuxStore> MakeWorldStore(const Glue &glue,
                                                         aux_state::VerusAuxStore::EpochProvider epoch,
                                                         aux_state::VerusAuxStore::FloorProvider floor);

// The active fault (tests only; empty: none).
const std::string &Fault();

} // namespace accelerator_codegen::verus_kit
